-- An append-only record of what operators and background jobs did: issuance, revocation, key exports, key and
-- certificate deletion, Vault writes and operator account changes. Rows can be added but never changed or removed,
-- whoever is connected, and the database stamps each row's time.

CREATE TABLE "AuditEvents" (
    "Id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "OccurredAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "Actor" CHARACTER VARYING(256) NOT NULL,
    "ActorIsSystem" BOOLEAN NOT NULL,
    "Action" CHARACTER VARYING(64) NOT NULL,
    "Succeeded" BOOLEAN NOT NULL,
    "EntityType" CHARACTER VARYING(64),
    "EntityId" INTEGER,
    "EntityName" CHARACTER VARYING(256),
    "Subject" CHARACTER VARYING(1024),
    "Thumbprint" CHARACTER VARYING(128),
    "TrustDomainId" INTEGER,
    "Detail" TEXT,
    CONSTRAINT "PK_AuditEvents" PRIMARY KEY ("Id")
);

CREATE INDEX "IX_AuditEvents_OccurredAt" ON "AuditEvents" USING btree ("OccurredAt");

CREATE INDEX "IX_AuditEvents_EntityType_EntityId" ON "AuditEvents" USING btree ("EntityType", "EntityId");

CREATE INDEX "IX_AuditEvents_Actor" ON "AuditEvents" USING btree ("Actor");

COMMENT ON TABLE "AuditEvents" IS 'Append-only audit trail of CA operations and operator account changes; rows are never updated or deleted';

COMMENT ON COLUMN "AuditEvents"."Id" IS 'Sequential event number';

COMMENT ON COLUMN "AuditEvents"."OccurredAt" IS 'When the event was recorded (UTC), set by the database on insert';

COMMENT ON COLUMN "AuditEvents"."Actor" IS 'Operator account (email) or system actor name, e.g. a recurring job, that performed the action';

COMMENT ON COLUMN "AuditEvents"."ActorIsSystem" IS 'True when the actor is a background job or machine client rather than a signed-in operator';

COMMENT ON COLUMN "AuditEvents"."Action" IS 'What happened, a stable dotted code such as certificate.issued, certificate.revoked or key.exported';

COMMENT ON COLUMN "AuditEvents"."Succeeded" IS 'False when the action was attempted and failed';

COMMENT ON COLUMN "AuditEvents"."EntityType" IS 'Kind of record acted on: CaCertificate, IssuedCertificate, Crl, ExternalCertificateRequest, TrustDomain or Operator; null when none';

COMMENT ON COLUMN "AuditEvents"."EntityId" IS 'Id of the record acted on; it may since have been deleted, so there is no foreign key';

COMMENT ON COLUMN "AuditEvents"."EntityName" IS 'Name of the record at the time of the event';

COMMENT ON COLUMN "AuditEvents"."Subject" IS 'Certificate subject DN at the time of the event, when the record is a certificate or request';

COMMENT ON COLUMN "AuditEvents"."Thumbprint" IS 'Certificate SHA-1 thumbprint (hex), when the record is a certificate';

COMMENT ON COLUMN "AuditEvents"."TrustDomainId" IS 'Trust domain of the record at the time of the event, when known';

COMMENT ON COLUMN "AuditEvents"."Detail" IS 'Further facts about the event in plain text, e.g. revocation reason, export format or roles granted';

CREATE FUNCTION audit_events_append_only() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW."OccurredAt" := clock_timestamp();
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'The audit trail is append-only: % on "AuditEvents" is not allowed', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER audit_events_append_only BEFORE INSERT OR UPDATE OR DELETE ON "AuditEvents"
    FOR EACH ROW EXECUTE FUNCTION audit_events_append_only();

CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON "AuditEvents"
    FOR EACH STATEMENT EXECUTE FUNCTION audit_events_append_only();

COMMENT ON FUNCTION audit_events_append_only() IS 'Stamps each new audit event with the database time and refuses updates, deletes and truncation';

-- The application's write role may add audit events, not change them (V0 grants it everything on new tables).
DO $$
DECLARE
    v_write TEXT := 'role_' || '${flyway:defaultSchema}' || '_write';
BEGIN
    IF EXISTS (SELECT FROM pg_roles WHERE rolname = v_write) THEN
        EXECUTE format('REVOKE UPDATE, DELETE, TRUNCATE ON TABLE %I FROM %I', 'AuditEvents', v_write);
    END IF;
END
$$;
